//  The indicator logic below is transplanted unchanged from QI_19_VolumeDelta (indicators/QI_19_VolumeDelta.cs);
//  its own documentation follows.
//
//  QI_19_VolumeDelta - Close-direction volume delta, 20-bar cumulative sum and 10-bar SMA
//
//  Lineage : split out of the "IBSFade" multi-strategy indicator, DataBox plots #21 and #22
//            (ORIG lines 1428-1443; volDelta series and volDeltaSma = SMA(volDelta, 10) at
//            357-360; per-bar delta in UpdateVolumeDelta, lines 1623-1634).
//  Provenance: Close-vs-prior-close signed volume is a proxy; true volume delta needs bid/ask (or at
//            least close-vs-open) classification. No authoritative definition for this form.
//  Concept : Close-direction volume delta as an order-flow proxy.
//  Formula : VolDelta[0]  = +Volume[0] if Close[0] > Close[1], -Volume[0] if Close[0] < Close[1],
//                           0 if unchanged; 0 on bar 0.
//            CumDelta20   = sum of VolDelta[0..19] only when CurrentBar > 20, else 0.
//            DeltaSMA10   = SMA(VolDelta, 10)[0] only when CurrentBar >= 10, else 0.
//  Quirks  : The cumulative guard is CurrentBar > 20 (strict), the SMA guard is >= 10; both
//            kept verbatim. ORIG gated its entire OnBarUpdate on CurrentBar >= 50 (ORIG 601),
//            so its volDelta series stayed 0 before bar 50 (affecting the 20-bar sum on bars
//            50-69 and the SMA on bars 50-58); the same gate is kept here. On INTRADAY charts
//            ORIG's gate also waits for its hidden daily series (ORIG 537); this standalone
//            does not, so the first ~20 bars after ORIG starts can differ on intraday charts.
// ============================================================================
#region Using declarations
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Cbi;
using NinjaTrader.Gui;
using NinjaTrader.Gui.Chart;
using NinjaTrader.Gui.SuperDom;
using NinjaTrader.Gui.Tools;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.Core.FloatingPoint;
using NinjaTrader.NinjaScript.Indicators;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

// This namespace holds Strategies in this folder and is required. Do not change it.
namespace NinjaTrader.NinjaScript.Strategies
{
	public class QS_19_VolumeDelta : Strategy
	{
		private Series<double>	volDelta;
		private SMA				volDeltaSma;
		private bool			disclaimerDrawn;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description					= "Volume delta: +Volume on an up close, -Volume on a down close, 0 otherwise; "
											+ "plus the 20-bar cumulative sum (0 until bar 21) and SMA(10) of the delta (0 until bar 10). "
											+ "Educational use only - not financial advice."
											+ " Backtest research strategy generated from QI_19_VolumeDelta and backtest/rules.yaml. Not financial advice. Places no orders in real time unless Backtest Only is turned off.";
				Name						= "QS_19_VolumeDelta";
				Calculate					= Calculate.OnBarClose;
				// Strategy defaults (backtest research; generated)
				EntriesPerDirection			= 1;
				EntryHandling				= EntryHandling.AllEntries;
				IsExitOnSessionCloseStrategy = false;
				StartBehavior				= StartBehavior.WaitUntilFlat;
				BarsRequiredToTrade			= 0;
				Slippage					= 1;
				DefaultQuantity				= 1;
				BacktestOnly				= true;
				TraceOrders					= false;
				IsOverlay					= false;
				DisplayInDataBox			= true;
				DrawOnPricePanel			= false;
				ScaleJustification			= ScaleJustification.Right;

				ShowDisclaimer				= false;

				AddPlot(new Stroke(Brushes.Gray,       2), PlotStyle.Bar,  "Vol Delta");
				AddPlot(new Stroke(Brushes.DodgerBlue, 2), PlotStyle.Line, "CumDelta 20");
				AddPlot(new Stroke(Brushes.Goldenrod,  2), PlotStyle.Line, "Delta SMA 10");
				AddLine(Brushes.DimGray, 0, "Zero");
			}
			else if (State == State.Configure)
			{
				// BacktestOnly: never let NinjaTrader synchronise the account with its own orders (BT16).
				if (BacktestOnly)
					StartBehavior = StartBehavior.WaitUntilFlat;
			}
			else if (State == State.DataLoaded)
			{
				volDelta		= new Series<double>(this);
				volDeltaSma		= SMA(volDelta, 10);
				disclaimerDrawn	= false;
			}
		}

		private void QiUpdate()
		{
			// ORIG module-wide warm-up gate (ORIG 537 / 601): volDelta stays 0 before bar 50.
			if (CurrentBar < 50)
				return;

			// Mirrors ORIG UpdateVolumeDelta (1623-1634): runs every bar BEFORE the value calc.
			UpdateVolumeDelta();
			Values[0][0] = volDelta[0];

			// ORIG 1429-1435, verbatim.
			double cumDelta = 0;
			if (CurrentBar > 20)
			{
				for (int i = 0; i < 20; i++)
					cumDelta += volDelta[i];
			}
			Values[1][0] = cumDelta;

			// ORIG 1440-1441, verbatim.
			double vdSmaVal = CurrentBar >= 10 ? volDeltaSma[0] : 0;
			Values[2][0] = vdSmaVal;

			DrawDisclaimerOnce();
		}

		// ------------------------------------------------------------------------------
		//  Backtest rule (generated from backtest/rules.yaml - do not edit by hand)
		//  module VolumeDelta | frame 15m | value cum_delta20 = CumDelta20[0] | ORIG lines 1429-1437; note: plot #21 CumDelta20 is the module's classified value
		//  long : x > 0
		//  short: x < 0
		// ------------------------------------------------------------------------------
		protected override void OnBarUpdate()
		{
			QiUpdate();
			ApplyRule();
		}

		// Backtest-only safety (validation/channel-a-backtest.md BT16): a Realtime-only guard is not
		// enough - an order submitted on the last historical bar carries into real time, and the
		// account-synchronising start behaviours make NinjaTrader place its own orders. With
		// BacktestOnly on, orders are allowed only during historical processing, only on the
		// Strategy Analyzer 'Backtest' account or a Sim/Playback account, and never on the last two
		// historical bars of a non-Backtest account; StartBehavior is forced to WaitUntilFlat.
		private bool OrdersAllowed()
		{
			if (State != State.Historical) return false;
			string acct = Account != null ? Account.Name : string.Empty;
			bool backtest = acct == "Backtest";
			bool research = backtest || acct.StartsWith("Sim") || acct.StartsWith("Playback");
			if (!research) return false;
			if (!backtest && CurrentBars[0] >= BarsArray[0].Count - 2) return false;
			return true;
		}

		private void ApplyRule()
		{
			if (BacktestOnly && !OrdersAllowed()) return;
			if (BarsInProgress != 0) return;

			double x = double.NaN;
			if (CumDelta20.IsValidDataPoint(0))
				x = CumDelta20[0];

			// A NaN / unset value maps to a flat target.
			int target = 0;
			if (!double.IsNaN(x))
			{
				bool goLong  = x > 0.0;
				bool goShort = x < 0.0;
				if (goLong)
					target = 1;
				else if (goShort)
					target = -1;
			}

			if (target == 1 && Position.MarketPosition != MarketPosition.Long)
				EnterLong(DefaultQuantity, "QS_L");
			else if (target == -1 && Position.MarketPosition != MarketPosition.Short)
				EnterShort(DefaultQuantity, "QS_S");
			else if (target == 0)
			{
				if (Position.MarketPosition == MarketPosition.Long)
					ExitLong("QS_XL", "QS_L");
				else if (Position.MarketPosition == MarketPosition.Short)
					ExitShort("QS_XS", "QS_S");
			}
		}

		// ORIG 1623-1634, verbatim.
		private void UpdateVolumeDelta()
		{
			if (CurrentBar < 1) { volDelta[0] = 0; return; }

			double priceChange = Close[0] - Close[1];
			if (priceChange > 0)
				volDelta[0] = Volume[0];
			else if (priceChange < 0)
				volDelta[0] = -Volume[0];
			else
				volDelta[0] = 0;
		}

		private void DrawDisclaimerOnce()
		{
			if (!ShowDisclaimer || disclaimerDrawn)
				return;

			Draw.TextFixed(this, "QI_Disclaimer", "Educational use only - not financial advice",
				TextPosition.BottomLeft, Brushes.Gray, new SimpleFont("Arial", 9),
				Brushes.Transparent, Brushes.Transparent, 0);
			disclaimerDrawn = true;
		}

		public override string DisplayName
		{
			get { return "QS 19 VolumeDelta"; }
		}

		#region Properties

		[NinjaScriptProperty]
		[Display(Name = "Backtest Only", Order = 0, GroupName = "Safety")]
		public bool BacktestOnly { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Show Disclaimer", Description = "Draw the educational-use disclaimer on the chart.",
			Order = 1, GroupName = "Display")]
		public bool ShowDisclaimer { get; set; }

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> VolDelta
		{
			get { return Values[0]; }
		}

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> CumDelta20
		{
			get { return Values[1]; }
		}

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> DeltaSMA10
		{
			get { return Values[2]; }
		}

		#endregion
	}
}
